from pathlib import Path

p=Path('dfs_app.py')
s=p.read_text(encoding='utf-8')

anchor='''    target_keys = {normalize_projection_player_name(name) for name in (target_names or []) if str(name).strip()}\n'''
block='''    target_keys = {normalize_projection_player_name(name) for name in (target_names or []) if str(name).strip()}\n\n    # FantasyPros official API. The key lives only in Streamlit Secrets.\n    if source_name == "FantasyPros":\n        try:\n            api_key = str(st.secrets.get("FANTASYPROS_API_KEY", "")).strip()\n        except Exception:\n            api_key = ""\n        if not api_key:\n            return {}\n        try:\n            season = _sticky_datetime.now(ZoneInfo("America/New_York")).year\n            response = requests.get(\n                f"https://api.fantasypros.com/public/v2/json/nfl/{season}/projections",\n                headers={"x-api-key": api_key, "Accept": "application/json"},\n                params={"positions": "QB:RB:WR:TE:K:DST", "scoring": "PPR"},\n                timeout=(5, 30),\n            )\n            response.raise_for_status()\n            payload = response.json()\n            fp_result = {}\n            is_fd = "fanduel" in str(platform_name).casefold()\n            for player in payload.get("players", []):\n                name = player.get("name") or player.get("player_name")\n                key = normalize_projection_player_name(name)\n                if not key or (target_keys and key not in target_keys):\n                    continue\n                stats = player.get("stats") or {}\n                # FantasyPros exposes consensus fantasy points with the projected\n                # stat line. FD is half-PPR; DK is PPR. Keep raw consensus rather\n                # than inventing bonuses from an average yardage projection.\n                candidates = (\n                    ("points_half", "fpts_half", "fantasy_points_half") if is_fd else\n                    ("points_ppr", "fpts_ppr", "fantasy_points_ppr")\n                )\n                value = next((stats.get(k) for k in candidates if stats.get(k) is not None), None)\n                if value is None:\n                    value = stats.get("points")\n                try:\n                    value = float(value)\n                except (TypeError, ValueError):\n                    continue\n                if np.isfinite(value) and value >= 0:\n                    fp_result[key] = value\n            return fp_result\n        except Exception as exc:\n            st.warning(f"FantasyPros API unavailable: {type(exc).__name__}: {exc}")\n            return {}\n'''
if 'if source_name == "FantasyPros":' not in s:
    if anchor not in s: raise SystemExit('projection target anchor not found')
    s=s.replace(anchor,block,1)

s=s.replace('for source_name in ("DFF", "DraftEdge"):', 'for source_name in ("DFF", "DraftEdge", "FantasyPros"):', 1)

start=s.index('def apply_external_projection_sources(')
end=s.find('\ndef ', start+5)
if end < 0: raise SystemExit('next function not found')
old=s[start:end]
new='''def apply_external_projection_sources(players_frame, dff_file, draftedge_file, platform_name='DraftKings'):\n    """Average all available external projections; never substitute internal estimates."""\n    result = players_frame.copy()\n    target_names = result["Name"].astype(str).tolist() if "Name" in result.columns else []\n    dff, dff_status = get_projection_source_data(dff_file, "DFF", platform_name, target_names)\n    draftedge, draftedge_status = get_projection_source_data(draftedge_file, "DraftEdge", platform_name, target_names)\n    fantasypros, fantasypros_status = get_projection_source_data(None, "FantasyPros", platform_name, target_names)\n    projections, sources = [], []\n    source_maps = (("DFF", dff), ("DraftEdge", draftedge), ("FantasyPros", fantasypros))\n    match_counts = {name: 0 for name, _ in source_maps}\n    averaged = missing_external = 0\n\n    for _, row in result.iterrows():\n        key = normalize_projection_player_name(row.get("Name", ""))\n        available = []\n        for source_name, values in source_maps:\n            value = values.get(key)\n            if value is not None:\n                available.append((source_name, float(value)))\n                match_counts[source_name] += 1\n        if available:\n            value = float(np.mean([v for _, v in available]))\n            source = " + ".join(name for name, _ in available)\n            if len(available) > 1:\n                source += " average"\n                averaged += 1\n        else:\n            value, source = 0.0, "Missing external projection"\n            missing_external += 1\n        projections.append(value)\n        sources.append(source)\n\n    result["Projection"] = projections\n    result["ProjectionSource"] = sources\n    st.caption(\n        f"External projection matches — DFF: {match_counts['DFF']} | "\n        f"DraftEdge: {match_counts['DraftEdge']} | FantasyPros: {match_counts['FantasyPros']} | "\n        f"multi-source averaged: {averaged} | missing: {missing_external}. "\n        f"FantasyPros: {fantasypros_status}."\n    )\n    return result\n\n'''
s=s[:start]+new+s[end+1:]
p.write_text(s,encoding='utf-8')
